package protocol

import "hijpass/config/uci"

// Custom describes the local entry point of a user-managed configuration.
// Its configuration file is not generated by the backend.
type Custom struct {
	BaseOptions
	Upstream Config
}

func (n *Custom) DecodeUCI(d *uci.Decoder) error {
	n.BaseOptions.decodeUCI(d)
	return d.Err()
}
func (n *Custom) Validate() error { return nil }
func init()                       { register("custom", func() Config { return &Custom{} }) }
